package com.robertobiggi.cardcollection.core.cardmarket

import com.robertobiggi.cardcollection.core.model.VariantType

/**
 * Japanese cards with Poké Ball and Master Ball reverse holo (e.g. Pokémon Card 151). On Cardmarket each variant is a
 * separate product, in a set "... - Poké Ball Reverse Holo", and TCGdex does not list them. The list is included in the app
 * (`cardmarket-ball-variants.tsv`) and generated by `gen_extra_sets.py` (Card-collector-db-gen repository) from the CardTrader sets.
 *
 * @param products Cardmarket product and CardTrader blueprint per set, number and variant.
 */
class BallVariants(private val products: Map<String, Map<VariantType, Product>>) {
    /**
     * Product of a variant.
     * @property cardmarketId Cardmarket `idProduct`.
     * @property blueprintId CardTrader blueprint (the card in the "... Poké Ball Reverse Holo" set), if known.
     */
    data class Product(val cardmarketId: Int, val blueprintId: Int?)

    /**
     * Poké Ball and Master Ball variants of a card.
     * @param setId String - TCGdex id of the set (e.g. "SV2a").
     * @param localId String - number of the card in the set.
     * @return Set<VariantType> - variants, empty if the card has none.
     */
    fun variantsOf(setId: String, localId: String): Set<VariantType> = products[key(setId, localId)]?.keys.orEmpty()

    /**
     * Cardmarket product of a variant.
     * @param setId String - TCGdex id of the set.
     * @param localId String - number of the card in the set.
     * @param variant VariantType - [VariantType.isBall].
     * @return Int? - `idProduct`, or null if the card does not have that variant.
     */
    fun productId(setId: String, localId: String, variant: VariantType): Int? = products[key(setId, localId)]?.get(variant)?.cardmarketId

    /**
     * CardTrader blueprint of a variant, to look up its listings.
     * @param setId String - TCGdex id of the set.
     * @param localId String - number of the card in the set.
     * @param variant VariantType - [VariantType.isBall].
     * @return Int? - blueprint id, or null if the card does not have that variant.
     */
    fun blueprintId(setId: String, localId: String, variant: VariantType): Int? = products[key(setId, localId)]?.get(variant)?.blueprintId

    companion object {
        /** List included in the app, read only once. */
        val bundled: BallVariants by lazy {
            val stream = BallVariants::class.java.getResourceAsStream("cardmarket-ball-variants.tsv")
                ?: return@lazy BallVariants(emptyMap())
            parse(stream.bufferedReader(Charsets.UTF_8).readLines())
        }

        /** The variants of a card are looked up by set (case-insensitive) and number (without leading zeros). */
        private fun normalizeNumber(raw: String): String {
            val head = raw.substringBefore('/').trim().uppercase()
            val stripped = head.trimStart('0')
            return if (stripped.isEmpty() && head.isNotEmpty()) "0" else stripped
        }

        private fun key(setId: String, localId: String) = "${setId.lowercase()}|${normalizeNumber(localId)}"

        /**
         * Reads the lines "set TAB number TAB variant TAB productId TAB blueprintId" (variant: POKE_BALL or MASTER_BALL; the last field is optional).
         * @param lines List<String> - lines of the file.
         * @return BallVariants - variants read; malformed lines are ignored.
         */
        fun parse(lines: List<String>): BallVariants {
            val products = HashMap<String, MutableMap<VariantType, Product>>()
            for (line in lines) {
                val p = line.split('\t')
                val variant = VariantType.fromName(p.getOrNull(2)?.trim())?.takeIf { it.isBall } ?: continue
                val id = p.getOrNull(3)?.trim()?.toIntOrNull() ?: continue
                if (p[0].isBlank() || p[1].isBlank()) continue
                products.getOrPut(key(p[0], p[1])) { java.util.EnumMap(VariantType::class.java) }[variant] = Product(id, p.getOrNull(4)?.trim()?.toIntOrNull())
            }
            return BallVariants(products)
        }
    }
}
